import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`buying-signals`,heroTitle:`Spot buying signals in minutes`,heroSubtitle:`Perplexity Computer scans job postings, tracks leadership changes, and builds your signal report - automatically.`,inputUrlCta:`Scan my target`,inputUrlPlaceholder:`e.g. Acme Corp`,inputUrlPrefill:`Go to {url} and research this company for buying signals. 1) Scan their careers page and job boards for new technical and leadership roles being hired. 2) Check LinkedIn for recent executive hires, departures, or leadership changes. 3) Use BuiltWith to detect any recent tech stack additions or changes. 4) Deliver a buying signal report that includes: an intent score (1-100), a list of trigger events with dates, a summary of tech stack changes, and a recommended outreach angle with a personalized email draft.`,heroOverlaySteps:[`Scanning job postings for new tech and leadership roles`,`Monitoring LinkedIn for recent executive changes and new hires`,`Detecting tech stack additions and vendor changes via BuiltWith`,`Intent score, trigger events, and outreach angle - ready to action`],generatingSteps:[`Researching {url} to identify company profile, industry, and tech footprint`,`Designing an agent to scan job boards, LinkedIn, and BuiltWith for buying signals`,`Configuring intent scoring logic and trigger event classification`,`Setting up the signal report with outreach recommendations and email drafts`],featureSectionTitle:`From company name to outreach plan`,featureCardTitles:[`Connects to your sales stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Pipedrive, Google Sheets, Slack, Gmail, Notion - Computer plugs into your tools so signals flow straight into your pipeline and outreach workflows.`,`Intent scores. Trigger event timelines. Tech stack change logs. Personalized outreach drafts. Computer delivers a signal report your reps can run with today.`],capabilitySectionTitle:`Your sales intel, on autopilot`,capabilitySectionSubtitle:`Enter a target company, step away, get a full buying signal report.`,capabilityCards:[{title:`Job Signal Scanning`,description:`Computer can scan careers pages and job boards for new technical roles, headcount surges, and hiring patterns that indicate budget and intent.`},{title:`Leadership Tracking`,description:`Computer can monitor LinkedIn for executive hires, departures, and role changes - the trigger events that open doors for outreach.`},{title:`Tech Stack Detection`,description:`Computer can detect new tools, vendor switches, and tech stack additions via BuiltWith - so you know exactly when a prospect is evaluating solutions.`},{title:`Connect Your Tools`,description:`Computer can push signals to Pipedrive, Google Sheets, Slack, Gmail, and more - build workflows across your entire sales stack.`},{title:`Remember & Learn`,description:`Computer can remember your ICP, target accounts, and past signals across sessions - so every scan builds on prior intelligence.`},{title:`Monitor & Alert`,description:`Computer can watch target accounts on a schedule and ping you in Slack when new buying signals appear - so you never miss a window.`}]});export{t as default};
